INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (1, 'S0ZNe2iqM54C', 'Laskar Pelangi', 'Laskar Pelangi telah menjadi international best seller, diterjemahkan ke dalam 40 bahasa asing. Telah terbit dalam 22 bahasa, diedarkan di lebih dari 130 negara. Melalui program beasiswa, Hirata meraih Master of Science (M.Sc.) bidang teori ekonomi dari Sheffield Hallam University, UK. Hirata juga mendapat beasiswa pendidikan sastra di IWP (International Writing Program), University of Iowa, USA.', 'Bentang Pustaka', '2008', 'https://books.google.com/books/content?id=S0ZNe2iqM54C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4.50, 96, '2026-11-06 00:21:56.405613');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (2, 'FQ_xml4y71EC', 'Sang Pemimpi', 'Sang Pemimpi adalah sebuah lantunan kisah kehidupan yang memesona dan akan membuat Anda percaya akan tenaga cinta, percaya pada kekuatan mimpi dan pengorbanan, lebih dari itu, akan membuat Anda percaya kepada Tuhan. Andrea akan membawa Anda berkelana menerobos sudut-sudut pemikiran di mana Anda akan menemukan pandangan yang berbeda tentang nasib, tantangan intelektualitas, dan kegembiraan yang meluap-luap, sekaligus kesedihan yang mengharu biru. Tampak komikal pada awalnya, selayaknya kenakalan remaja biasa, tapi kemudian tanpa Anda sadari, kisah dan karakter-karakter dalam buku ini lambat laun menguasai Anda. Karena potret-potret kecil yang menawan akan menghentakkan Anda pada rasa humor yang halus namun memiliki efek filosofis yang meresonansi. Karena arti perjuangan hidup dalam kemiskinan yang membelit dan cita-cita yang gagah berani dalam kisah dua orang tokoh utama buku ini: Arai dan Ikal akan menuntun Anda dengan semacam keanggunan dan daya tarik agar Anda dapat melihat ke dalam diri sendiri dengan penuh pengharapan, agar Anda menolak semua keputusasaan dan ketakberdayaan Anda sendiri. “Kita tak kan pernah mendahului nasib!” teriak Arai. “Kita akan sekolah ke Prancis, menjelajahi Eropa sampai ke Afrika! Apa pun yang terjadi!” [Bentang, Novel, Inspirasi, Motivasi, Indonesia]', 'Bentang Pustaka', '2006', 'https://books.google.com/books/content?id=FQ_xml4y71EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4.50, 68, '2026-11-06 00:21:57.164662');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (3, 'FV18DLfHz0MC', 'Edensor', 'Novel ketiga dari tetralogi Laskar Pelangi ini bercerita tentang petualangan Ikal dan Arai di Eropa. Setelah berhasil memperoleh beasiswa ke Prancis, Ikal dan Arai, mengalami banyak kejadian yang orang biasa sebut sebagai kejutan budaya. Banyak kebiasaan dan peradaban Eropa yang berlainan sama sekali dengan peradaban yang selama ini mereka pahami sebagai orang Indonesia,khususnya Melayu. Di dalam buku ini juga Ikal dan Arai kembali menuai karma akibat kenakalan-kenalan yang pernah mereka lakukan semasa kecil dan remaja dulu. Pembaca akan dibawa ke dalam petualangan mereka menyusuri Eropa dengan berbagai pengalaman yang mencengangkan, mencekam, membuat terbahak, sekaligus berurai air mata. Aku ingin mendaki puncak tantangan, menerjang batu granit kesulitan, menggoda mara bahaya, dan memecahkan misteri dengan sains. Aku ingin menghirup berupa-rupa pengalaman lalu terjun bebas menyelami labirin lika-liku hidup yang ujungnya tak dapat disangka. Aku mendamba kehidupan dengan kemungkinan-kemungkinan yang bereaksi satu sama lain seperti benturan molekul uranium: meletup tak terduga-duga, menyerap, mengikat, mengganda, berkembang, terurai, dan berpencar ke arah yang mengejutkan. Aku ingin ke tempat-tempat yang jauh, menjumpai beragam bahasa dan orang-orang asing. Aku ingin berkelana, menemukan arahku dengan membaca bintang gemintang. Aku ingin mengarungi padang dan gurun-gurun, ingin melepuh terbakar matahari, limbung dihantam angin, dan menciut dicengkeram dingin. Aku ingin kehidupan yang menggetarkan, penuh dengan penaklukan. Aku ingin hidup! Ingin merasakan sari pati hidup! Novel ini kian meneguhkan kehadiran tetralogi Laskar Pelangi sebagai karya unggul yang pasti disukai pembaca. —Ahmad Tohari, sastrawan Andrea Hirata membuatku mabuk kepayang!—Linda Christanty, cerpenis Berpotensi memberikan letupan inspirasi bagi pembacanya.—Tabloid Wanita Indonesia [Bentang, Motivasi, Inspirasi, Novel, Indonesia]', 'Bentang Pustaka', '2007-01-01', 'https://books.google.com/books/content?id=FV18DLfHz0MC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4.00, 64, '2026-11-06 00:21:58.755735');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (4, 'vzD-3U60S34C', 'Maryamah Karpov', 'Keberanian dan keteguhan hati telah membawa Ikal pada banyak tempat dan peristiwa. Sudut-sudut dunia telah dia kunjungi demi menemukan A Ling. Apa pun Ikal lakukan demi perempuan itu. Keberaniannya ditantang ketika tanda-tanda keberadaan A Ling tampak. Dia tetap mencari, meski tanda-tanda itu masih samar.Dapatkah keduanya bertemu kembali? [Mizan, Bentang, Novel, Inspirasi, Indonesia]', 'Bentang Pustaka', '2008-11-01', 'https://books.google.com/books/content?id=vzD-3U60S34C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3.50, 34, '2026-11-06 00:22:00.398812');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (5, 'YLo8DwAAQBAJ', 'Cantik Itu Luka', 'Di satu sore, seorang perempuan bangkit dari kuburannya setelah dua puluh satu tahun kematian. Kebangkitannya menguak kutukan dan tragedi keluarga, yang terentang sejak akhir masa kolonial perpaduan antara epik keluarga yang dibalut roman, kisah hantu, kekejaman politik, mitologi, dan petualangan. Dari kekasih yang lenyap ditelan kabut hingga seorang ibu yang menginginkan bayi buruk rupa.', 'Gramedia Pustaka Utama', '2018-05-07', 'https://books.google.com/books/content?id=YLo8DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:02.032934');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (6, 'SyVYnFwHoGsC', 'Lelaki Harimau', NULL, 'Gramedia Pustaka Utama', '2004', 'https://books.google.com/books/content?id=SyVYnFwHoGsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:03.622106');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (7, '2sA8DwAAQBAJ', 'Seperti Dendam, Rindu Harus Dibayar Tuntas', 'Di puncak rezim yang penuh kekerasan, kisah ini bermula dari satu peristiwa: dua orang polisi memerkosa seorang perempuan gila, dan dua bocah melihatnya melalui lubang di jendela. Dan seekor burung memutuskan untuk tidur panjang. Di tengah kehidupan yang keras dan brutal, si burung tidur merupakan alegori tentang kehidupan yang tenang dan damai, meskipun semua orang berusaha membangunkannya. * * * “Eka Kurniawan: an unconventional writer.” – Weekender, The Jakarta Post “Dalam Seperti Dendam, Rindu Harus Dibayar Tuntas, Eka menulis dengan semangat bermain-main yang cerdik dan lihai.” – Anton Kurnia, Jawa Pos “Membaca novel-novel Eka Kurniawan adalah membaca asal-muasal setiap kejadian.” – Aris Kurniawan, Koran Tempo “Dialog dengan ‘kemaluan’ jadi ruang permenungan, melahirkan keyakinan-keyakinan tak biasa.” – Widyanuari Eko Putra, Kompas', 'Gramedia Pustaka Utama', '2019-05-27', 'https://books.google.com/books/content?id=2sA8DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:05.357621');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (8, '-jE5DwAAQBAJ', 'Anak Semua Bangsa', 'Pada seri kedua ini menceritakan perjuangan batin Minke dimana istrinya yakni Annelis harus dibawa paksa ke Belanda. Tetapi pihak keluarga Nyi Ontosoroh tidak tinggal diam, sehingga dikirimlah seorang teman sekolah Minke yang bernama Panji Darman alias Jan Depperste untuk memantau keadaan Annelis di sana. Komunikasi melalui surat-menyurat. Di sisi lain Minke tak mau tinggal diam melawan keadaan. Dia terus belajar kepada Nyi Ontosoroh tentang banyak hal. Mulai dari menjalankan bisnis, urusan hukum, hingga menjadi inspirasinya untuk menulis.', 'Hasta Mitra', '2002-10-01', 'https://books.google.com/books/content?id=-jE5DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:13.142406');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (22, 'z5xkAAAAMAAJ', 'Deru Campur Debu', NULL, NULL, '1991', 'https://books.google.com/books/content?id=z5xkAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, NULL, '2026-11-06 00:22:59.399663');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (9, '1WHwDwAAQBAJ', 'Jejak Langkah', 'Kehadiran roman sejarah ini, bukan hanya untuk mengisi episode berbangsa yang ada di titik persalinan yang ditentukan dan ditentukan, tetapi juga memuat isu kesusastraan yang sangat minim menggarap periode pelik ini. Karena itu hadirnya roman ini memberi bacaan alternatif bagi kita untuk melihat jalan dan gelombang sejarah yang lain dan dari sisinya yang berbeda. Tetralogi ini dibagi dalam format empat buku. Bagian ini dapat juga kita artikan sebagai bagian dari gerakan yang hadir dalam beberapa periode. Dan roman tiga ini, Jejak Langkah, adalah fase pengorganisasian perlawanan. Minke memobilisasi segala daya untuk melawan bercokolnya kekuasaan Hindia yang sudah berabad-abad seumurnya. Namun Minke tak memilih perlawanan. Ia memilih jalan jurnalistik dengan membuat sebanyak-banyaknya bacaan Pribumi. Medan Prajaji yang paling terkenal tentu saja. Dengan koran ini, Minke bereru-berseru kepada rakyat Pribumi tiga hal: meningkatkan boikot, berorganisasi, dan menggunakan budaya feodalistik. Sekaligus lewat langkah jurnalistik, Minke berseru-seru: ''Didiklah rakyat dengan organisasi dan didiklah penguasa dengan kekuatan.', 'Hasta Mitra', '2000-10-10', 'https://books.google.com/books/content?id=1WHwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:14.876779');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (10, '4WHwDwAAQBAJ', 'Rumah Kaca', 'Rumah Kaca muncul bab terakhir dari kuartet epik Pramoedya, yang bertempat di Hindia Belanda pada pergantian abad. Novel kepahlawanan, hasrat, dan pengkhianatan, novel ini memberikan kesimpulan spektakuler untuk seri yang dipuji sebagai salah satu karya hebat sastra modern. Pada awal Rumah Kaca, Minke, penulis dan pemimpin gerakan pembangkang, sekarang dipenjara - dan narasinya telah beralih ke Pangemanann, seorang mantan polisi, yang memiliki tugas memata-matai dan melaporkan mereka yang melanjutkan perjuangan untuk kemerdekaan . Tapi pemburu menjadi buruan. Pangemanann adalah korban dari hati nuraninya sendiri dan telah datang untuk mengagumi lawan-lawannya. Dia harus memutuskan apakah hukum itu untuk melindungi hak-hak rakyat atau untuk mengendalikan rakyat. Dia takut kehilangan posisinya, keluarganya, dan harga diriny', 'Hasta Mitra', '2001-01-01', 'https://books.google.com/books/content?id=4WHwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:15.638982');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (11, 'OKFOEAAAQBAJ', 'Pulang', 'Paris, Mei 1968 Ketika gerakan mahasiswa berkecamuk di Paris, Dimas Suryo, seorang eksil politik Indonesia, bertemu Vivienne Deveraux, mahasiswa yang ikut demonstrasi melawan pemerintahan Prancis. Pada saat yang sama, Dimas menerima kabar dari Jakarta; Hananto Prawiro, sahabatnya, ditangkap tentara dan dinyatakan tewas. Di tengah kesibukan mengelola Restoran Tanah Air di Paris, Dimas bersama tiga kawannya-Nugroho, Tjai, dan Risjaf—terus-menerus dikejar rasa bersalah karena kawan-kawannya di Indonesia dikejar, ditembak, atau menghikang begitu saja dalam perburuan peristiwa 30 September. Apalagi dia tak bisa melupakan Surti Anandari—isteri Hananto—yang bersama ketiga anaknya berbulan-bulan diinterogasi tentara. Jakarta, Mei 1998. Lintang Utara, puteri Dimas dari perkawinan dengan Vivienne Deveraux, akhirnya berhasil memperoleh visa masuk Indonesia untuk merekam pengalaman keluarga korban tragedi 30 September sebagai tugas akhir kuliahnya. Apa yang terkuak oleh Lintang bukan sekedar masa lalu ayahnya dengan Surti Anandari, tetapi juga bagaimana sejarah paling berdarah di negerinya mempunyai kaitan dengan Ayah dan kawan-kawan ayahnya. Bersama Sedara Alam, putera Hananto, Lintang menjadi saksi mata apa yang kemudian menjadi kerusuhan terbesar dalam sejarah Indonesia: kerusuhan Mei 1998 dan jatuhnya Presiden Indonesia yang sudah berkuasa selama 32 tahun. Pulang adalah sebuah drama keluarga, persahabatan, cinta, dan pengkhianatan berlatar belakang tiga peristiwa bersejarah: Indonesia 30 September 1965, Prancis Mei 1968, dan Indonesia Mei 1998. #Pulang #BukuAnak #CeritaAnak #EdukasiAnak #BacaanAnak #DongengAnak #AnakCerdas #BukuPolitik #SejarahIndonesia #EsaiPolitik #WawasanKebangsaan #PemikiranKritis #BukuBestseller #RekomendasiBuku #BukuBagus #BukuBaru #KoleksiBuku #TokoBukuOnline #BacaanBermanfaat #LiterasiIndonesia', 'Kepustakaan Populer Gramedia', '2021-11-12', 'https://books.google.com/books/content?id=OKFOEAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:18.191493');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (12, 'e-ZDDwAAQBAJ', 'Laut Bercerita', 'Jakarta, Maret 1998 Di sebuah senja, di sebuah rumah susun di Jakarta, mahasiswa bernama Biru Laut disergap empat lelaki tak dikenal. Bersama kawan-kawannya, Daniel Tumbuan, Sunu Dyantoro, Alex Perazon, dia dibawa ke sebuah tempat yang tak dikenal. Berbulan-bulan mereka disekap, diinterogasi, dipukul, ditendang, digantung, dan disetrum agara bersedia menjawab satu pertanyaan penting: siapakah yang berdiri di balik gerakan aktivis dan mahasiswa saat itu. Jakarta, Juni 1998 Keluarga Arya Wibisono, seperti biasa, pada hari Minggu sore memasak bersama, menyediakan makanan kesukaan Biru Laut. Sang ayah akan meletakkan satu piring untuk dirinya, satu piring untuk sang ibu, Biru Laut, dan satu piring untuk si bungsu Asmara Jati. Mereka duduk menanti dan menanti. Tapi Biru Laut tak kunjung muncul. Jakarta, 2000 Asmara Jati, adik Biru Laut, beserta Tim Komisi Orang Hilang yang dipimpin Aswin Pradana mencoba mencari jejak mereka yang hilang serta merekam dan mempelajari testimoni mereka yang kembali. Anjani, kekasih Laut, para orangtua dan istri aktivis yang hilang menuntut kejelasan tentang anggota keluarga mereka. Sementara Biru Laut, dari dasar laut yang sunyi bercerita kepada kita, kepada dunia tentang apa yang terjadi pada dirinya dan kawan-kawannya. Laut Bercerita, novel terbaru Leila S. Chudori, bertutur tentang kisah keluarga yang kehilangan, sekumpulan sahabat yang merasakan kekosongan di dada, sekelompok orang yang gemar menyiksa dan lancar berkhianat, sejumlah keluarga yang mencari kejelasan makam anaknya, dan tentang cinta yang tak akan luntur.', 'Kepustakaan Populer Gramedia', '2017-10-23', 'https://books.google.com/books/content?id=e-ZDDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:22:19.973559');
