INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (20, 'yas8AAAAYAAJ', 'Beyond Good and Evil', '"Beyond Good and Evil" is Nietzsche at his best. In the book the philosopher attempts to systematically sum up his philosophy through a collection of 296 aphorisms grouped into nine different chapters based on their common theme.', 'Tribeca Books', '1907', 'https://books.google.com/books/content?id=yas8AAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5.00, 2, '2026-11-06 00:22:56.188394');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (21, 'yqlkAAAAMAAJ', 'Hujan Bulan Juni', 'Poems.', NULL, '1994', 'https://books.google.com/books/content?id=yqlkAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, NULL, '2026-11-06 00:22:57.813286');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (23, 'WoWfCgAAQBAJ', 'Milk and Honey', 'The #1 New York Times bestseller that ignited a worldwide poetry movement, milk and honey is a boundary-breaking collection of poetry, prose and illustrations about survival. About the experience of violence, abuse, love, loss, and femininity. Written and illustrated while Rupi Kaur was a university student, milk and honey soon became a word-of-mouth phenomenon, topping bestseller lists worldwide. It remains a bestselling sensation, the poetry book for the modern world. Organized into four sections: the hurting, the loving, the breaking, the healing Original, minimalist illustrations accompany Meant to be read start to finish, compelling readers to return to favorite pages long after their first read Kaur is also the author of the sun and her flowers and home body; the three combined have sold more than 11 million copies in over 43 languages “Rupi Kaur Live,” the first-of-its-kind poetry special, appears on Prime Video. Ideal gift or self-purchase for fans of modern poetry A noble companion, milk and honey heals as it takes readers through a journey of the most bitter moments in life, showing readers the sweetness in those moments, because it is everywhere, if you are willing to look. Immerse yourself in the lyrical feast by the author lauded by The New Republic as “the Writer of the Decade.”', 'Andrews McMeel Publishing', '2015-10-06', 'https://books.google.com/books/content?id=WoWfCgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4.00, 35, '2026-11-06 00:23:05.163576');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (24, 'I1o4DgAAQBAJ', 'The Design of Everyday Things', 'One of the world''s great designers shares his vision of "the fundamental principles of great and meaningful design", that''s "even more relevant today than it was when first published" (Tim Brown, CEO, IDEO). Even the smartest among us can feel inept as we fail to figure out which light switch or oven burner to turn on, or whether to push, pull, or slide a door. The fault, argues this ingenious -- even liberating -- book, lies not in ourselves, but in product design that ignores the needs of users and the principles of cognitive psychology. The problems range from ambiguous and hidden controls to arbitrary relationships between controls and functions, coupled with a lack of feedback or other assistance and unreasonable demands on memorization. The Design of Everyday Things shows that good, usable design is possible. The rules are simple: make things visible, exploit natural relationships that couple function and control, and make intelligent use of constraints. The goal: guide the user effortlessly to the right action on the right control at the right time. The Design of Everyday Things is a powerful primer on how -- and why -- some products satisfy customers while others only frustrate them.', 'Hachette UK', '2013-11-05', 'https://books.google.com/books/content?id=I1o4DgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5.00, 1, '2026-11-06 00:23:11.835668');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (25, '6nDz8Am4zfEC', 'Ways of Seeing', '“The relation between what we see and what we know is never settled” -- so opens John Berger’s revolutionary million-copy bestseller on how to look at art John Berger''s Ways of Seeing is one of the most stimulating and the most influential books on art in any language. First published in 1972, it was based on the BBC television series about which the Sunday Times critic commented: "This is an eye-opener in more ways than one: by concentrating on how we look at paintings . . . he will almost certainly change the way you look at pictures." By now he has.', 'Penguin Books', '1990-12-01', 'https://books.google.com/books/content?id=6nDz8Am4zfEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3.50, 6, '2026-11-06 00:23:13.660766');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (26, 'nnV4EAAAQBAJ', 'Steal Like an Artist', 'Unlock your creativity. An inspiring guide to creativity in the digital age, Steal Like an Artist presents ten transformative principles that will help readers discover their artistic side and build a more creative life. Nothing is original, so embrace influence, school yourself through the work of others, remix and reimagine to discover your own path. Follow interests wherever they take you—what feels like a hobby may turn into you life’s work. Forget the old cliché about writing what you know: Instead, write the book you want to read, make the movie you want to watch. And finally, stay Smart, stay out of debt, and risk being boring in the everyday world so that you have the space to be wild and daring in your imagination and your work. “Brilliant and real and true.”—Rosanne Cash', 'Hachette UK', '2012-02-28', 'https://books.google.com/books/content?id=nnV4EAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:23:18.749244');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (27, 'oZhagX6UWOMC', 'A Brief History of Time', '#1 NEW YORK TIMES BESTSELLER A landmark volume in science writing by one of the great minds of our time, Stephen Hawking’s book explores such profound questions as: How did the universe begin—and what made its start possible? Does time always flow forward? Is the universe unending—or are there boundaries? Are there other dimensions in space? What will happen when it all ends? Told in language we all can understand, A Brief History of Time plunges into the exotic realms of black holes and quarks, of antimatter and “arrows of time,” of the big bang and a bigger God—where the possibilities are wondrous and unexpected. With exciting images and profound imagination, Stephen Hawking brings us closer to the ultimate secrets at the very heart of creation.', 'Bantam', '2011-05-04', 'https://books.google.com/books/content?id=oZhagX6UWOMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4.00, 18, '2026-11-06 00:23:25.38481');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (28, 'Gwe0ict60PMC', 'The Selfish Gene', '"The Selfish Gene is remarkable in several ways. First published in 1976, aimed at a general audience and written by a then little-known young lecturer in zoology at Oxford University, The Selfish Gene rapidly became highly influential. The important biological work of such figures as W. D. Hamilton and Robert Trivers was introduced to a wider public for the first time. But that was not all. Drawing together the threads of contemporary research in Neo-Darwinism into a powerful vision of the living world viewed through the eyes of genes as the units of selection, it was a significant contribution to biological thought. The full explanatory power of the gene''s eye view was presented, in fine non-technical prose, for the first time in one short volume, bringing novel insights to those working in the field and inspiring whole new areas of research. Yet even that is not all. It has been widely acclaimed too for its literary qualities. Here is a book that set a new standard in science writing for the wider public, a modern masterpiece that fresh generations of aspiring young scientists would seek to emulate."--BOOK JACKET.', 'Oxford University Press, USA', '2006', 'https://books.google.com/books/content?id=Gwe0ict60PMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:23:35.971947');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (29, 'WEn4DAAAQBAJ', 'The Hidden Life of Trees', 'A NEW YORK TIMES, WASHINGTON POST, AND WALL STREET JOURNAL BESTSELLER • One of the most beloved books of our time: an illuminating account of the forest, and the science that shows us how trees communicate, feel, and live in social networks. After reading this book, a walk in the woods will never be the same again. “Breaks entirely new ground ... [Peter Wohlleben] has listened to trees and decoded their language. Now he speaks for them.”—The New York Review of Books NAMED ONE OF THE BEST BOOKS OF THE YEAR BY BRAINPICKINGS • HONORABLE MENTION: SEJ Rachel Carson Environment Book Award • Shortlisted: Audible International Book of the Year Award • Books For a Better Life Award • Indie Choice Award—Nonfiction Book of the Year Are trees social beings? In The Hidden Life of Trees forester and author Peter Wohlleben convincingly makes the case that, yes, the forest is a social network. He draws on groundbreaking scientific discoveries to describe how trees are like human families: tree parents live together with their children, communicate with them, support them as they grow, share nutrients with those who are sick or struggling, and even warn each other of impending dangers. Wohlleben also shares his deep love of woods and forests, explaining the amazing processes of life, death, and regeneration that he has observed in his woodland. “A declaration of love and an engrossing primer on trees, brimming with facts and an unashamed awe for nature.”—Washington Post “Heavily dusted with the glitter of wonderment.”—The New Yorker Includes a Note From a Forest Scientist by Dr.Suzanne Simard Published in Partnership with the David Suzuki Institute', 'Greystone Books', '2016-09-13', 'https://books.google.com/books/content?id=WEn4DAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5.00, 3, '2026-11-06 00:23:42.151791');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (30, '_BrB7kg19RgC', 'Guns, Germs, and Steel', '**WINNER OF THE PULITZER PRIZE** ''A book of big questions, and big answers'' Yuval Noah Harari, bestselling author of Sapiens Why has human history unfolded so differently across the globe? And what can it teach us about our current crisis? Jared Diamond puts the case that geography and biogeography, not race, moulded the contrasting fates of Europeans, Asians, Native Americans, sub-Saharan Africans, and aboriginal Australians. An ambitious synthesis of history, biology, ecology and linguistics, Guns, Germs and Steel is a ground-breaking and humane work of popular science that can provide expert insight into our modern world. ''The most absorbing account on offer of the emergence of a world divided between have and have-nots... Never before put together so coherently, with such a combination of expertise, charm and compassion'' The Times', 'Random House', '2013-07-04', 'https://books.google.com/books/content?id=_BrB7kg19RgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-06 00:23:48.556149');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (32, 'CkVvAAAAMAAJ', 'A History of Modern Indonesia', 'Counter In this second edition, all parts of the book have been revised and sections added wherever new research has required this, greater attention has been given to economic issues, and two new chapters have been written on the period since 1965. The bibliography has been brought completely up to date. Indonesia is the forth most populous nation of the earth and a major producer of oil and other resources. It is also the most populous nation of the Islamic world and at the same time heir to vigorous pre-Islamic traditions and complex cultural heritages of the many islands which make up the Republic. Its colourful history, from the coming of Islam c. 1300 to the present day, is described in this comprehensive work. The emphasis throughout the book is on the history of the Indonesian peoples themselves. An essential narrative of political history is provided as well as discussions of social, cultural and economic affairs. Chapter bibliographies are included to guide readers to the most recent scholarly works on the subject. Behind this structure, the book poses the important question of how the diverse but related linguistic and ethnic communities of the Indonesian archipelago became a unified nation. Attention is therefore given first to those influences which set the scene for the post-1300 era of Indonesian history: the spread of Islam; early European contact; the emergence of the new Indonesian states and the variety of indigenous cultural, literary and religious traditions. The turbulent seventeenth century and eighteenth centuries are then analysed in terms of the largely inconclusive struggles for hegemony among Indonesian states and the Dutch. The nineteenth century saw Dutch colonial rule gradually imposed throughout the archipelago, and the twentieth century opened with quite new issues which were by now common to most of the peoples of Indonesia. Islamic revivalism and anti-colonial movements further helped to draw Indonesia together, a process which culminated in the revolution and independence. Since then, Indonesia''s unification has made many achievements possible, but has not prevented the emergence of persistence of serious problems. Without political or religious bias, using both western and Indonesian sources, this history assists the serious study of both the past and the present of this beautiful and important Southeast Asian nation.', NULL, '1981', 'https://books.google.com/books/content?id=CkVvAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, NULL, '2026-11-06 00:23:52.854725');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (33, 'fFCjDQAAQBAJ', 'Atomic Habits', '***COMING 9TH DECEMBER 2025 - THE ATOMIC HABITS WORKBOOK: OFFICIAL COMPANION TO THE #1 WORLDWIDE BESTSELLER. PREORDER NOW*** THE PHENOMENAL INTERNATIONAL BESTSELLER: OVER 25 MILLION COPIES SOLD WORLDWIDE Transform your life with tiny changes in behaviour, starting now. People think that when you want to change your life, you need to think big. But world-renowned habits expert James Clear has discovered another way. He knows that real change comes from the compound effect of hundreds of small decisions: doing two push-ups a day, waking up five minutes early, or holding a single short phone call. He calls them atomic habits. In this ground-breaking book, Clears reveals exactly how these minuscule changes can grow into such life-altering outcomes. He uncovers a handful of simple life hacks (the forgotten art of Habit Stacking, the unexpected power of the Two Minute Rule, or the trick to entering the Goldilocks Zone), and delves into cutting-edge psychology and neuroscience to explain why they matter. Along the way, he tells inspiring stories of Olympic gold medalists, leading CEOs, and distinguished scientists who have used the science of tiny habits to stay productive, motivated, and happy. These small changes will have a revolutionary effect on your career, your relationships, and your life. ________________________________ A NEW YORK TIMES AND SUNDAY TIMES BESTSELLER ''A supremely practical and useful book.'' Mark Manson, author of The Subtle Art of Not Giving A F*ck ''James Clear has spent years honing the art and studying the science of habits. This engaging, hands-on book is the guide you need to break bad routines and make good ones.'' Adam Grant, author of Originals ''Atomic Habits is a step-by-step manual for changing routines.'' Books of the Month, Financial Times ''A special book that will change how you approach your day and live your life.'' Ryan Holiday, author of The Obstacle is the Way', 'Random House', '2018-10-18', 'https://books.google.com/books/content?id=fFCjDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4.00, 4, '2026-11-06 00:23:59.297839');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (34, 'P7BkAAAAMAAJ', 'Bumi Manusia', NULL, NULL, '1981', 'https://books.google.com/books/content?id=P7BkAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, NULL, '2026-11-08 10:57:43.172601');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (35, 'DDbtj7RHVdEC', 'One Hundred Years of Solitude', '"Get your "A" in gear! They''''re today''''s most popular study guides-with everything you need to succeed in school. Written by Harvard students for students, since its inception "SparkNotes(TM) has developed a loyal community of dedicated users and become a major education brand. Consumer demand has been so strong that the guides have expanded to over 150 titles. "SparkNotes''''(TM) motto is "Smarter, Better, Faster because: - They feature the most current ideas and themes, written by experts. - They''''re easier to understand, because the same people who use them have also written them. - The clear writing style and edited content enables students to read through the material quickly, saving valuable time. And with everything covered--context; plot overview; character lists; themes, motifs, and symbols; summary and analysis, key facts; study questions and essay topics; and reviews and resources--you don''''t have to go anywhere else!', 'Spark Notes', '2002-07-15', 'https://books.google.com/books/content?id=DDbtj7RHVdEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4.50, 8, '2026-11-08 10:57:51.293014');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (36, 'oYAh96Xo4pUC', 'The Great Gatsby', NULL, NULL, '1925', 'https://books.google.com/books/content?id=oYAh96Xo4pUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3.00, 3, '2026-11-08 10:57:55.693731');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (37, 'cpAREAAAQBAJ', 'Nineteen Eighty-Four', '''If you want a picture of the future, imagine a boot stamping on a human face--forever.'' Nineteen Eighty-Four (1949), George Orwell''s final novel, was completed in difficult conditions shortly before his early death. It is one of the most influential and widely-read novels of the post-war period, and has been a huge international bestseller over many decades. Continually in print, it has long been controversial, both in its immediate Cold War context and in later history. It is in some ways a realist novel, but in others is more akin to a work of science fiction, a dystopia or a satire. It also has strong affiliations to Gothic in its plotting, motifs and affective states. Full of horror and terror, it contains prophetic dreams and a central character who thinks of himself as a ''monster'', a ''ghost'' and ''already dead''. Like Frankenstein and Dracula, it is fascinated by the power of a documentary remnant addressed to an unknown reader.', NULL, '2021', 'https://books.google.com/books/content?id=cpAREAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-08 10:58:00.610756');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (38, 'DWpt7x5U7gEC', 'The Stranger', 'Get your A in gear! They''re today''s most popular study guides-with everything you need to succeed in school. Written by Harvard students for students, since its inception SparkNotes(TM) has developed a loyal community of dedicated users and become a major education brand. Consumer demand has been so strong that the guides have expanded to over 150 titles. SparkNotes''(TM) motto is Smarter, Better, Faster because: - They feature the most current ideas and themes, written by experts. - They''re easier to understand, because the same people who use them have also written them. - The clear writing style and edited content enables students to read through the material quickly, saving valuable time. And with everything covered--context; plot overview; character lists; themes, motifs, and symbols; summary and analysis, key facts; study questions and essay topics; and reviews and resources--you don''t have to go anywhere else!', 'Spark Notes', '2002', 'https://books.google.com/books/content?id=DWpt7x5U7gEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4.00, 7, '2026-11-08 10:58:06.221193');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (39, 'zaPoAQAAQBAJ', 'The Myth of Sisyphus', 'In this profound and moving philosophical statement, Camus poses the fundamental question: If human existence has no meaning, is life worth living? ''What I touch, what resists me - that is what I understand'' As Camus argues, if there is no God to give meaning to our lives, humans must take on that purpose themselves. This is our ''absurd'' task, like Sisyphus condemned forever to roll a rock up a hill. Written during the bleakest days of the Second World War, The Myth of Sisyphus argues for an acceptance of reality that encompasses revolt, passion and, above all, liberty, gained through an awareness of pure existence. This volume contains several other essays, including lyrical evocations of the sunlit cities of Algiers and Oran, the settings of his great novels The Outsider and The Plague. The writings in this volume are all, in their own way, hymns to the physical world and the elemental pleasures of living. Translated by Justin O''Brien With an afterword by James Wood', 'Penguin UK', '2013-10-31', 'https://books.google.com/books/content?id=zaPoAQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-08 10:58:10.11807');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (40, 'G3VCAQAAIAAJ', 'Meditations', NULL, NULL, '1887', 'https://books.google.com/books/content?id=G3VCAQAAIAAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-08 10:58:14.0987');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (43, 'q_zWDgAAQBAJ', 'Educated', 'THE MULTI-MILLION COPY BESTSELLER A BETWEEN THE COVERS PICK Selected as a book of the year by AMAZON, THE TIMES, SUNDAY TIMES, GUARDIAN, NEW YORK TIMES, ECONOMIST, NEW STATESMAN, VOGUE, IRISH TIMES, IRISH EXAMINER and RED MAGAZINE ''One of the best books I have ever read . . . unbelievably moving'' Elizabeth Day ''An extraordinary story, beautifully told'' Louise O''Neill ''A memoir to stand alongside the classics . . . compelling and joyous'' Sunday Times Tara Westover grew up preparing for the end of the world. She was never put in school, never taken to the doctor. She did not even have a birth certificate until she was nine years old. At sixteen, to escape her father''s radicalism and a violent older brother, Tara left home. What followed was a struggle for self-invention, a journey that gets to the heart of what an education is and what it offers: the perspective to see one''s life through new eyes, and the will to change it. ''It will make your heart soar'' Guardian ''Jaw-dropping and inspiring, everyone should read this book'' Stylist ''Absolutely superb . . . so gripping I could hardly breathe'' Sophie Hannah', 'Random House', '2018-02-20', 'https://books.google.com/books/content?id=q_zWDgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4.50, 2, '2026-11-08 10:58:47.717114');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (44, 'NJ3KITbBHSMC', 'Silent Spring', NULL, NULL, '1962', 'https://books.google.com/books/content?id=NJ3KITbBHSMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', NULL, NULL, '2026-11-08 11:03:36.991437');
INSERT INTO public.books (book_id, api_book_id, title, description, publisher, published_date, cover_image, google_average_rating, google_ratings_count, created_at) VALUES (45, '9peoEQAAQBAJ', 'Sapiens', 'The fourth and final volume of the graphic adaptation of Yuval Noah Harari’s global phenomenon Sapiens, illustrating how rapid advances transform society, reshape capitalism and propel us into the technological age. Five hundred years ago, humankind made a startling discovery: our own collective ignorance. Determined to finally uncover the secrets of the universe, modern humans have learned how to control the world and how to produce more of everything. But did modernity make us any happier? Sapiens: A Graphic History – The Age of Revolutions takes us on a riveting ride from the Scientific Revolution through the Industrial Revolution to the dawn of the AI Revolution. Along the way, we find out why the Roman Empire had the best army but no technological edge, how banks create money out of thin air, how clocks came to rule our lives, and why humans remain dissatisfied despite unprecedented abundance. Join Skyman, Mx Computer and Death on the psychiatrist’s couch as they deal with humanity’s quest for omniscience and immortality. Follow the passionate affair between Lady Empire and Scientifik, as together they seek to conquer all the blank spaces on the map. And jump on board with Detective Lopez as she unravels a worldwide conspiracy to break the laws of biology. In this thrilling conclusion to the graphic adaptation of Yuval Noah Harari’s bestselling Sapiens, humanity faces its most pressing challenge ever: figuring out how to control an alien intelligence. Will we succeed? Or will we become trapped inside the dreams of smart machines? Brimming with wit, insight and inventive visuals, this final volume in the series reveals how humans became the irresponsible gods of Planet Earth, and how we can make wiser and more compassionate choices in future.', 'Random House', '2026-11-05', 'https://books.google.com/books/content?id=9peoEQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', NULL, NULL, '2026-11-08 11:03:38.327029');
